const res = $('Resources').first().json;
const state = res?.attributes?.current_state || 'offline';
const log = String($input.first().json.data ?? '');
const lines = log.split('\n').filter(l => l.includes('players online'));
const last = lines.length ? lines[lines.length - 1].trim() : '';
const m = last.match(/There are (\d+) of a max of (\d+) players online:\s*(.*)$/);
const players = (state === 'running' && m && m[3].trim())
  ? m[3].split(',').map(s => s.trim()).filter(Boolean) : [];
return [{ json: { status: state, count: m ? Number(m[1]) : 0, max: m ? Number(m[2]) : null, players } }];

const data = $input.first().json;

function parseList(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
}[c]));

const day = value => {
  if (!value) return '—';
  const d = new Date(value);
  return Number.isNaN(d.getTime())
    ? '—'
    : d.toISOString().slice(0, 10);
};

const invites = parseList(data.invites);
const registrations = parseList(data.registrations);

const inviteRows = invites.map(i => {
  const actions = `
    ${i.status === 'available' ? `
      <form method="POST" action="/webhook/wl-admin"
        onsubmit="return confirm('Deze uitnodiging intrekken?')">
        <input type="hidden" name="action" value="revoke">
        <input type="hidden" name="id" value="${esc(i.id)}">
        <button class="revoke" type="submit">Intrekken</button>
      </form>
    ` : ''}
    <form method="POST" action="/webhook/wl-admin"
      onsubmit="return confirm('Deze uitnodiging verbergen uit het dashboard?')">
      <input type="hidden" name="action" value="delete">
      <input type="hidden" name="id" value="${esc(i.id)}">
      <button class="delete" type="submit">Verbergen</button>
    </form>
  `;

  return `
  <tr>
    <td>${day(i.created_at)}</td>
    <td>${esc(i.status === 'available' ? 'beschikbaar' : i.status)}</td>
    <td>${esc(i.access_days)} dagen</td>
    <td>${esc(i.use_count ?? 0)} / ${esc(i.max_uses ?? 1)}</td>
    <td>${day(i.expires_at)}</td>
    <td>${actions}</td>
  </tr>`;
}).join('');

const regRows = registrations.map(r => `
<tr>
  <td>${esc(r.username ?? r.minecraft_username)}</td>
  <td>${esc(r.real_name)}</td>
  <td>${day(r.created_at)}</td>
  <td>${day(r.expires_at ?? r.access_expires_at)}</td>
  <td>${esc(r.status)}</td>
</tr>`).join('');

const html = `<!doctype html>
<html lang="nl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Whitelist beheer</title>
<style>
body{font-family:system-ui,sans-serif;max-width:900px;margin:40px auto;padding:0 16px;background:#14161a;color:#e8e8e8}
input,button{padding:10px;margin:6px 0;border-radius:6px;border:1px solid #444;background:#1f2228;color:#fff;font-size:16px;width:100%;box-sizing:border-box}
button{background:#4caf50;border:0;cursor:pointer}
button.revoke{background:#c88724}
button.delete{background:#b33a3a}
table{width:100%;border-collapse:collapse;font-size:14px}
td,th{padding:8px;border-bottom:1px solid #333;text-align:left;vertical-align:top}
.card{background:#1b1e24;padding:16px;border-radius:10px;margin-bottom:16px;overflow-x:auto}
td form{margin:0 0 5px}
td button{min-width:95px}
</style>
</head>
<body>
<h1>Whitelist beheer</h1>

<div class="card">
<h3>Nieuwe uitnodigingslink</h3>
<form method="POST" action="/webhook/wl-admin">
<input type="hidden" name="action" value="create">

<label>Minecraft-toegang (dagen)</label>
<input type="number" name="days" value="365" min="1" max="3650" required>

<label>Link geldig (dagen)</label>
<input type="number" name="linkdays" value="7" min="1" max="90" required>

<label>Maximum aantal gebruiken</label>
<input type="number" name="max_uses" value="1" min="1" max="1000" required>

<button type="submit">Link aanmaken</button>
</form>
</div>

<div class="card">
<h3>Uitnodigingen</h3>
<table>
<tr>
<th>Aangemaakt</th>
<th>Status</th>
<th>Toegang</th>
<th>Gebruikt / maximum</th>
<th>Link geldig tot</th>
<th>Acties</th>
</tr>
${inviteRows || '<tr><td colspan="6">Nog geen uitnodigingen.</td></tr>'}
</table>
</div>

<div class="card">
<h3>Geregistreerde spelers</h3>
<table>
<tr><th>Minecraft</th><th>Naam</th><th>Aangemaakt</th><th>Toegang tot</th><th>Status</th></tr>
${regRows || '<tr><td colspan="5">Nog geen registraties.</td></tr>'}
</table>
</div>
</body>
</html>`;

return [{ json: { html } }];

const input = $input.first().json;
const body = input.body ?? input;

const linkDays = Math.min(
  90,
  Math.max(1, Number(body.linkdays ?? 7))
);

const accessDays = Math.min(
  3650,
  Math.max(1, Number(body.days ?? 365))
);

const maxUses = Math.min(
  1000,
  Math.max(1, Number(body.max_uses ?? 1))
);

return [{
  json: {
  linkdays: linkDays,
  accessdays: accessDays,
  max_uses: maxUses,
  created_by: 'admin_n8n'
}
}];

const saved = $input.first().json;

const token = saved.token;
const linkDays = $('uitnodiging voorbereiden').first().json.linkdays;
const accessDays = saved.access_days;
const maxUses = saved.max_uses;

if (!token) {
  throw new Error('Geen uitnodigingstoken ontvangen vanuit PostgreSQL.');
}

const link = `http://10.20.236.220:5678/webhook/wl-join?token=${encodeURIComponent(token)}`;

const html = `
<!DOCTYPE html>
<html lang="nl">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Uitnodiging aangemaakt</title>
</head>
<body style="font-family:Arial,sans-serif;max-width:700px;margin:40px auto;padding:20px">
  <h1>Uitnodiging aangemaakt</h1>
  <p>De uitnodigingslink is aangemaakt.</p>
  <p>De link is ${linkDays} dagen geldig.</p>
  <p>De Minecraft-whitelisttoegang is ingesteld op ${accessDays} dagen.</p>
  <p>Deze uitnodigingslink kan maximaal ${maxUses} keer gebruikt worden.</p>
  <p><a href="${link}">${link}</a></p>
  <button onclick="navigator.clipboard.writeText(document.getElementById('link').textContent)">Kopieer link</button>
  <p id="link" style="word-break:break-all">${link}</p>
  <p><a href="/webhook/wl-admin">Terug naar beheer</a></p>
</body>
</html>`;

return [{
  json: {
    ...saved,
    token,
    link,
    html
  }
}];

const row = $input.first().json;

let invite = row.invite;
if (typeof invite === 'string') {
  try {
    invite = JSON.parse(invite);
  } catch {
    invite = null;
  }
}

const token = String(row.token || '');
const geldig = invite && invite.id && token.length > 0;

const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/"/g, '&quot;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const html = geldig
  ? `<!doctype html>
<html lang="nl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Minecraft whitelist aanvragen</title>
</head>
<body>
<h1>Minecraft whitelist aanvragen</h1>
<p>Je uitnodiging is geldig. Vul je gegevens in.</p>
<form method="POST" action="/webhook/wl-register">
<input type="hidden" name="token" value="${escapeHtml(token)}">
<label>Minecraft-gebruikersnaam</label><br>
<input name="username" minlength="3" maxlength="16"
pattern="[A-Za-z0-9_]{3,16}" required><br><br>
<label>Echte naam</label><br>
<input name="real_name" maxlength="100" required><br><br>
<button type="submit">Registreren</button>
</form>
</body>
</html>`
  : `<!doctype html>
<html lang="nl">
<head><meta charset="utf-8"><title>Uitnodiging ongeldig</title></head>
<body>
<h1>Uitnodiging ongeldig</h1>
<p>Deze uitnodiging is ongeldig, verlopen of al gebruikt.</p>
</body>
</html>`;

return [{
  json: {
    geldig: !!geldig,
    html,
    invite_id: geldig ? invite.id : null
  }
}];

const body = $input.first().json.body ?? {};
const username = String(body.username ?? '').trim();
const realName = String(body.real_name ?? '').trim();
const token = String(body.token ?? '').trim();

const fouten = [];

if (!/^[A-Za-z0-9_]{3,16}$/.test(username)) {
  fouten.push('De Minecraft-gebruikersnaam moet 3 tot 16 letters, cijfers of underscores bevatten.');
}

if (!realName || realName.length > 100) {
  fouten.push('Vul een echte naam in van maximaal 100 tekens.');
}

if (!/^[a-fA-F0-9]{64}$/.test(token)) {
  fouten.push('De uitnodigingstoken ontbreekt of is ongeldig.');
}

return [{
  json: {
    geldig: fouten.length === 0,
    username,
    real_name: realName,
    token,
    foutmelding: fouten.join(' ')
  }
}];
